package com.example.flashcardapp.main

import android.os.Bundle
import android.widget.Button
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.example.flashcardapp.R
import com.example.flashcardapp.data.Topic
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

class TopicSelectionActivity : AppCompatActivity() {

    private lateinit var adapter: TopicSelectionAdapter
    private lateinit var flashcardDAO: FlashcardDAO

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_topic_selection)

        flashcardDAO = FlashcardDAO(this)
        flashcardDAO.open()

        val rvTopics = findViewById<RecyclerView>(R.id.rv_topics)
        val btnSave = findViewById<Button>(R.id.btn_save)

        rvTopics.layoutManager = LinearLayoutManager(this)

        // Load all topics asynchronously using coroutines
        lifecycleScope.launch(Dispatchers.IO) {
            val allTopics: List<Topic> = flashcardDAO.getAllTopics()
            withContext(Dispatchers.Main) {
                adapter = TopicSelectionAdapter(allTopics)
                rvTopics.adapter = adapter
            }
        }

        btnSave.setOnClickListener {
            saveSelectedTopicsToDatabase(adapter.getSelectedTopics())
        }
    }

    private fun saveSelectedTopicsToDatabase(topics: List<Topic>) {
        lifecycleScope.launch(Dispatchers.IO) {
            for (topic in topics) {
                flashcardDAO.updateTopicSelection(topic.id, topic.selected)
            }
            withContext(Dispatchers.Main) {
                finish() // Close activity after saving
            }
        }
    }

    override fun onDestroy() {
        flashcardDAO.close()
        super.onDestroy()
    }
}
